#[test]
fn public_dx11_rejects_unimplemented_hal_features_at_fl91() {
    let required = std::env::var_os("WGPU_DX11_REQUIRE_HARDWARE").is_some_and(|value| value == "1");
    let mut descriptor = InstanceDescriptor::new_without_display_handle();
    descriptor.backends = Backends::DX11;
    let instance = Instance::new(descriptor);
    let adapters = poll_ready(instance.enumerate_adapters(Backends::DX11));
    let Some(adapter) = adapters.into_iter().next() else {
        assert!(
            !required,
            "strict mode requires a physical FL9_1 D3D11 adapter"
        );
        println!("SKIP: public D3D11 enumeration found no physical FL9_1 adapter");
        return;
    };
    let info = adapter.get_info();
    assert_eq!(info.backend, Backend::Dx11);
    assert!(info.driver_info.contains("FL9_1"), "{info:?}");
    assert!(info.driver_info.contains("physical"), "{info:?}");
    let features = adapter.features();
    let unsupported = [
        Features::PIPELINE_CACHE,
        Features::EXPERIMENTAL_RAY_QUERY,
        Features::CLIP_DISTANCES,
        Features::SHADER_F16,
    ];
    for feature in unsupported {
        assert!(
            !features.contains(feature),
            "the adapter must not expose {feature:?}"
        );
        let result = poll_ready(adapter.request_device(&DeviceDescriptor {
            label: Some("reject a feature without a D3D11 HAL implementation"),
            required_features: feature,
            required_limits: adapter.limits(),
            ..Default::default()
        }));
        assert!(
            result.is_err(),
            "device creation unexpectedly accepted {feature:?}"
        );
    }
    let downlevel = adapter.get_downlevel_capabilities();
    assert!(!downlevel.flags.contains(DownlevelFlags::SHADER_F16_IN_F32));
    let (device, _) = poll_ready(adapter.request_device(&DeviceDescriptor {
        label: Some("public DX11 FL9_1 shader-capability validation test"),
        required_features: Features::empty(),
        required_limits: adapter.limits(),
        ..Default::default()
    }))
    .expect("request the selected FL9_1 device");
    expect_validation_error(&device, "WGSL clip_distances without its feature", || {
        drop(device.create_shader_module(ShaderModuleDescriptor {
            label: Some("unavailable FL9_1 clip_distances"),
            source: ShaderSource::Wgsl(
                "enable clip_distances; struct Output { @builtin(position) position: vec4f, @builtin(clip_distances) distances: array<f32, 1> } @vertex fn main() -> Output { var output: Output; output.position = vec4f(0.0, 0.0, 0.5, 1.0); output.distances[0] = 0.5; return output; }".into(),
            ),
        }));
    });
    expect_validation_error(
        &device,
        "WGSL quantizeToF16 without its downlevel capability",
        || {
            drop(device.create_shader_module(ShaderModuleDescriptor {
                label: Some("unavailable FL9_1 quantizeToF16"),
                source: ShaderSource::Wgsl(
                    "@fragment fn main(@location(0) value: f32) -> @location(0) vec4f { let quantized = quantizeToF16(value); return vec4f(quantized, 0.0, 0.0, 1.0); }".into(),
                ),
            }));
        },
    );
    println!(
        "Hardware: name={:?} vendor={:#06x} device={:#06x} driver_info={:?} requested=FL9_1 actual=FL9_1 software=false",
        info.name, info.vendor, info.device, info.driver_info
    );
    println!(
        "PASS: public adapter withheld PIPELINE_CACHE, EXPERIMENTAL_RAY_QUERY, CLIP_DISTANCES, and SHADER_F16; clip-distance and quantizeToF16 shader modules failed Core validation"
    );
}

#[test]
fn public_dx11_runs_static_but_rejects_dynamic_shader_loops_at_fl91() {
    let required = std::env::var_os("WGPU_DX11_REQUIRE_HARDWARE").is_some_and(|value| value == "1");
    let mut descriptor = InstanceDescriptor::new_without_display_handle();
    descriptor.backends = Backends::DX11;
    let instance = Instance::new(descriptor);
    let adapters = poll_ready(instance.enumerate_adapters(Backends::DX11));
    let Some(adapter) = adapters.into_iter().next() else {
        assert!(
            !required,
            "strict mode requires a physical FL9_1 D3D11 adapter"
        );
        println!("SKIP: public D3D11 enumeration found no physical FL9_1 adapter");
        return;
    };
    let info = adapter.get_info();
    let downlevel = adapter.get_downlevel_capabilities();
    assert_eq!(info.backend, Backend::Dx11);
    assert!(info.driver_info.contains("FL9_1"), "{info:?}");
    assert!(info.driver_info.contains("physical"), "{info:?}");
    assert!(downlevel.limits.shader_loops);
    assert!(!downlevel.limits.shader_dynamic_loops);
    println!(
        "Hardware: name={:?} vendor={:#06x} device={:#06x} driver_info={:?} requested=FL9_1 actual=FL9_1 software=false statically_unrolled_loops=true dynamic_loops=false",
        info.name, info.vendor, info.device, info.driver_info
    );
    let (device, queue) = poll_ready(adapter.request_device(&DeviceDescriptor {
        label: Some("public DX11 FL9_1 shader-loop test"),
        required_features: Features::empty(),
        required_limits: adapter.limits(),
        ..Default::default()
    }))
    .expect("request the selected FL9_1 device");
    let shader = device.create_shader_module(ShaderModuleDescriptor {
        label: Some("FL9_1 selected-entry shader-loop test"),
        source: ShaderSource::Wgsl(
            r#"
            @group(0) @binding(0) var<uniform> loop_limit: f32;
            struct VertexOutput {
                @builtin(position) position: vec4f,
                @location(0) loop_value: f32,
            }
            fn dynamic_loop_helper() -> f32 {
                var i = 0.0;
                loop {
                    if i >= loop_limit { break; }
                    i += 1.0;
                }
                return i;
            }
            fn static_vertex_loop() -> f32 {
                var value = 0.0;
                for (var i = 0.0; i < 4.0; i += 1.0) { value += 0.25; }
                return value;
            }
            fn static_fragment_loop() -> f32 {
                var value = 0.0;
                for (var i = 0.0; i < 3.0; i += 1.0) { value += 0.25; }
                return value;
            }
            @vertex fn vertex_static(@location(0) p: vec2f) -> VertexOutput {
                var output: VertexOutput;
                output.position = vec4f(p, 0.0, 1.0);
                output.loop_value = static_vertex_loop();
                return output;
            }
            @fragment fn fragment_static(input: VertexOutput) -> @location(0) vec4f {
                return vec4f(input.loop_value, static_fragment_loop(), 0.0, 1.0);
            }
            @vertex fn vertex_dynamic() -> @builtin(position) vec4f {
                return vec4f(dynamic_loop_helper(), 0.0, 0.0, 1.0);
            }
            @fragment fn fragment_dynamic() -> @location(0) vec4f {
                return vec4f(dynamic_loop_helper(), 0.0, 0.0, 1.0);
            }
            "#
            .into(),
        ),
    });
    let targets = [Some(ColorTargetState {
        format: TextureFormat::Rgba8Unorm,
        blend: None,
        write_mask: ColorWrites::ALL,
    })];
    let create_pipeline = |vertex_entry, fragment_entry, vertex_buffers| {
        device.create_render_pipeline(&RenderPipelineDescriptor {
            label: Some("FL9_1 shader-loop pipeline"),
            layout: None,
            vertex: VertexState {
                module: &shader,
                entry_point: Some(vertex_entry),
                compilation_options: PipelineCompilationOptions::default(),
                buffers: vertex_buffers,
            },
            primitive: PrimitiveState::default(),
            depth_stencil: None,
            multisample: MultisampleState::default(),
            fragment: Some(FragmentState {
                module: &shader,
                entry_point: Some(fragment_entry),
                compilation_options: PipelineCompilationOptions::default(),
                targets: &targets,
            }),
            multiview_mask: None,
            cache: None,
        })
    };

    let attributes = [VertexAttribute {
        format: VertexFormat::Float32x2,
        offset: 0,
        shader_location: 0,
    }];
    let vertex_buffers = [Some(VertexBufferLayout {
        array_stride: 8,
        step_mode: VertexStepMode::Vertex,
        attributes: &attributes,
    })];
    let pipeline = create_pipeline("vertex_static", "fragment_static", &vertex_buffers);
    expect_validation_error_containing(
        &device,
        "dynamic vertex shader loop",
        "UnsupportedShaderLoops",
        || drop(create_pipeline("vertex_dynamic", "fragment_dynamic", &[])),
    );
    expect_validation_error_containing(
        &device,
        "dynamic fragment shader loop",
        "UnsupportedShaderLoops",
        || {
            drop(create_pipeline(
                "vertex_static",
                "fragment_dynamic",
                &vertex_buffers,
            ))
        },
    );

    let target = device.create_texture(&TextureDescriptor {
        label: Some("FL9_1 statically unrolled loop output"),
        size: Extent3d {
            width: 8,
            height: 8,
            depth_or_array_layers: 1,
        },
        mip_level_count: 1,
        sample_count: 1,
        dimension: TextureDimension::D2,
        format: TextureFormat::Rgba8Unorm,
        usage: TextureUsages::RENDER_ATTACHMENT | TextureUsages::COPY_SRC,
        view_formats: &[],
    });
    let view = target.create_view(&TextureViewDescriptor::default());
    let vertex_data: Vec<u8> = [-1.0f32, -1.0, 3.0, -1.0, -1.0, 3.0]
        .into_iter()
        .flat_map(f32::to_ne_bytes)
        .collect();
    let vertex = device.create_buffer(&BufferDescriptor {
        label: Some("FL9_1 static-loop full-screen triangle"),
        size: vertex_data.len() as u64,
        usage: BufferUsages::VERTEX,
        mapped_at_creation: true,
    });
    vertex
        .get_mapped_range_mut(..)
        .expect("map static-loop vertices")
        .copy_from_slice(&vertex_data);
    vertex.unmap();
    let readback = device.create_buffer(&BufferDescriptor {
        label: Some("FL9_1 static-loop output readback"),
        size: 8 * 256,
        usage: BufferUsages::COPY_DST | BufferUsages::MAP_READ,
        mapped_at_creation: false,
    });
    let mut encoder = device.create_command_encoder(&CommandEncoderDescriptor {
        label: Some("FL9_1 static-loop render"),
    });
    {
        let mut pass = encoder.begin_render_pass(&RenderPassDescriptor {
            label: Some("FL9_1 static-loop render pass"),
            color_attachments: &[Some(RenderPassColorAttachment {
                view: &view,
                depth_slice: None,
                resolve_target: None,
                ops: Operations {
                    load: LoadOp::Clear(Color::BLACK),
                    store: StoreOp::Store,
                },
            })],
            depth_stencil_attachment: None,
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        pass.set_pipeline(&pipeline);
        pass.set_vertex_buffer(0, vertex.slice(..));
        pass.draw(0..3, 0..1);
    }
    encoder.copy_texture_to_buffer(
        TexelCopyTextureInfo {
            texture: &target,
            mip_level: 0,
            origin: Origin3d::ZERO,
            aspect: TextureAspect::All,
        },
        TexelCopyBufferInfo {
            buffer: &readback,
            layout: TexelCopyBufferLayout {
                offset: 0,
                bytes_per_row: Some(256),
                rows_per_image: Some(8),
            },
        },
        Extent3d {
            width: 8,
            height: 8,
            depth_or_array_layers: 1,
        },
    );
    let submission = queue.submit([encoder.finish()]);
    let (sender, receiver) = std::sync::mpsc::channel();
    readback
        .slice(..)
        .map_async(MapMode::Read, move |result| sender.send(result).unwrap());
    device
        .poll(PollType::Wait {
            submission_index: Some(submission),
            timeout: Some(Duration::from_secs(10)),
        })
        .expect("wait for FL9_1 static-loop draw");
    receiver
        .recv_timeout(Duration::from_secs(10))
        .expect("static-loop readback callback")
        .expect("map static-loop output");
    {
        let data = readback.slice(..).get_mapped_range().expect("mapped data");
        for y in 0..8 {
            for x in 0..8 {
                let offset = y * 256 + x * 4;
                let expected = [255, 191, 0, 255];
                for (channel, (&actual, expected)) in
                    data[offset..offset + 4].iter().zip(expected).enumerate()
                {
                    assert!(
                        actual.abs_diff(expected) <= 1,
                        "pixel ({x}, {y}) channel {channel}: expected {expected}, observed {actual}"
                    );
                }
            }
        }
    }
    readback.unmap();
    println!(
        "PASS: FL9_1 static vertex and fragment loops rendered 64/64 expected pixels; core rejected dynamic loops before FXC"
    );
}

